package com.laundry.management.inventory.operations;

import static com.laundry.management.inventory.operations.StockStore.*;
import com.laundry.management.auth.security.permission.PermissionCodes;
import com.laundry.management.operations.application.OperationsAccess;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service @Transactional(readOnly=true)
public class StockQueries {
    private final StockStore db;private final StockService commands;private final OperationsAccess access;private final Clock clock;
    public StockQueries(StockStore db,StockService commands,OperationsAccess access,Clock clock){this.db=db;this.commands=commands;this.access=access;this.clock=clock;}
    private record Sql(String text,List<Object> args) {}
    private void validate(StockDtos.Filter f){access.branch(f.branchId());if(f.page()<0||f.size()<1||f.size()>100||f.search()!=null&&f.search().length()>150)throw StockFailure.invalid("INVALID_PAGE_OR_SEARCH");
        if(f.from()!=null&&f.to()!=null&&!f.from().isBefore(f.to()))throw StockFailure.invalid("INVALID_PERIOD");
        if(f.status()!=null&&!Set.of("DRAFT","RECORDED","CANCELLED","IN_TRANSIT","PARTIALLY_RECEIVED","RECEIVED").contains(f.status()))throw StockFailure.invalid("INVALID_STATUS");
        if(f.warehouseId()!=null)db.one("SELECT id FROM warehouses WHERE id=? AND branch_id=?",f.warehouseId(),access.branch(f.branchId()));
        if(f.itemId()!=null)db.one("SELECT id FROM inventory_items WHERE id=? AND branch_id=?",f.itemId(),access.branch(f.branchId()));}
    private String search(String s){return "%"+s.trim().toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%";}
    private Map<String,Object> page(List<Map<String,Object>> items,long count,StockDtos.Filter f){return Map.of("items",items,"page",f.page(),"size",f.size(),"totalElements",count,"totalPages",(count+f.size()-1)/f.size());}
    private Sql docs(StockDtos.Filter f){validate(f);List<Object>a=new ArrayList<>();long branch=access.branch(f.branchId());StringBuilder where=new StringBuilder(" WHERE (d.branch_id=? OR d.destination_branch_id=?)");a.add(branch);a.add(branch);
        // A cross-branch document is visible only when every involved branch is accessible.
        where.append(" AND (d.destination_branch_id IS NULL OR EXISTS(SELECT 1 FROM user_branches ub WHERE ub.user_id=? AND ub.branch_id=d.destination_branch_id)) AND EXISTS(SELECT 1 FROM user_branches ub WHERE ub.user_id=? AND ub.branch_id=d.branch_id)");a.add(access.actor());a.add(access.actor());
        if(f.warehouseId()!=null){where.append(" AND (d.warehouse_id=? OR d.destination_warehouse_id=?)");a.add(f.warehouseId());a.add(f.warehouseId());}
        if(f.kind()!=null){where.append(" AND d.kind=?");a.add(f.kind().name());}if(f.status()!=null){where.append(" AND d.status=?");a.add(f.status());}
        if(f.supplierId()!=null){where.append(" AND d.supplier_id=?");a.add(f.supplierId());}if(f.from()!=null){where.append(" AND d.business_at>=?");a.add(time(f.from()));}if(f.to()!=null){where.append(" AND d.business_at<?");a.add(time(f.to()));}
        if(f.search()!=null&&!f.search().isBlank()){where.append(" AND LOWER(d.code) LIKE ? ESCAPE '!'");a.add(search(f.search()));}return new Sql(where.toString(),a);}
    public Object documents(StockDtos.Filter f){commands.require(PermissionCodes.INVENTORY_DOCUMENT_READ);var q=docs(f);long count=db.jdbc().queryForObject("SELECT COUNT(*) FROM stock_documents d"+q.text,Long.class,q.args.toArray());
        String sort=switch(Objects.toString(f.sort(),"newest")){case "oldest"->"d.business_at ASC,d.id ASC";case "code"->"d.code ASC,d.id ASC";case "newest"->"d.business_at DESC,d.id DESC";default->throw StockFailure.invalid("INVALID_SORT");};
        List<Object>a=new ArrayList<>(q.args);a.add(f.size());a.add(Math.multiplyExact((long)f.page(),f.size()));var rows=db.rows("SELECT d.current_snapshot,u.display_name actor_name FROM stock_documents d JOIN users u ON u.id=d.created_by"+q.text+" ORDER BY "+sort+" LIMIT ? OFFSET ?",a.toArray());
        var result=new LinkedHashMap<>(page(rows.stream().map(r->{var snapshot=publicSnapshot(db.parse(r.get("currentSnapshot")));snapshot.put("actorName",r.get("actorName"));return snapshot;}).toList(),count,f));
        result.put("summary",db.one("SELECT COALESCE(SUM(CASE WHEN d.status NOT IN ('DRAFT','CANCELLED') THEN d.total_value ELSE 0 END),0) total_value FROM stock_documents d"+q.text,q.args.toArray()));return result;}
    public Map<String,Object> detail(long id,Long branch){commands.require(PermissionCodes.INVENTORY_DOCUMENT_READ);var d=commands.document(id,branch);var snap=publicSnapshot(db.parse(d.get("currentSnapshot")));snap.put("transit",db.rows("SELECT * FROM stock_transit WHERE document_id=? ORDER BY line_number",id));return snap;}
    public Object history(long id,Long branch,int page,int size){commands.require(PermissionCodes.INVENTORY_AUDIT_READ);commands.document(id,branch);if(page<0||size<1||size>100)throw StockFailure.invalid("INVALID_PAGE_OR_SEARCH");long count=db.jdbc().queryForObject("SELECT COUNT(*) FROM stock_revisions WHERE document_id=?",Long.class,id);
        var rows=db.rows("SELECT * FROM stock_revisions WHERE document_id=? ORDER BY revision DESC LIMIT ? OFFSET ?",id,size,(long)page*size);for(var row:rows){row.put("snapshot",publicSnapshot(db.parse(row.get("snapshot"))));row.put("beforeSnapshot",row.get("beforeSnapshot")==null?null:publicSnapshot(db.parse(row.get("beforeSnapshot"))));row.put("effects",db.list(row.get("effects")));}return Map.of("items",rows,"totalElements",count,"totalPages",(count+size-1)/size,"page",page,"size",size);}
    private Map<String,Object> publicSnapshot(Map<String,Object> snapshot){snapshot.remove("effectiveEffects");return snapshot;}
    private Sql scope(StockDtos.Filter f,String alias){validate(f);List<Object>a=new ArrayList<>();StringBuilder q=new StringBuilder(" WHERE "+alias+".branch_id=?");a.add(access.branch(f.branchId()));
        if(f.warehouseId()!=null){q.append(" AND "+alias+".warehouse_id=?");a.add(f.warehouseId());}if(f.itemId()!=null){q.append(" AND i.id=?");a.add(f.itemId());}if(f.categoryId()!=null){q.append(" AND i.category_id=?");a.add(f.categoryId());}
        if(f.search()!=null&&!f.search().isBlank()){q.append(" AND (LOWER(i.name) LIKE ? ESCAPE '!' OR LOWER(i.code) LIKE ? ESCAPE '!')");a.add(search(f.search()));a.add(search(f.search()));}return new Sql(q.toString(),a);}
    private static final String POOLS=" FROM warehouses w JOIN inventory_items i ON i.branch_id=w.branch_id JOIN inventory_units u ON u.id=i.base_unit_id LEFT JOIN stock_balances b ON b.warehouse_id=w.id AND b.item_id=i.id";
    public Object balances(StockDtos.Filter f){commands.require(PermissionCodes.INVENTORY_STOCK_READ);var s=scope(f,"w");String where=s.text.replace("w.warehouse_id","w.id");long count=db.jdbc().queryForObject("SELECT COUNT(*)"+POOLS+where,Long.class,s.args.toArray());List<Object>a=new ArrayList<>(s.args);a.add(f.size());a.add((long)f.page()*f.size());
        var rows=db.rows("SELECT w.id warehouse_id,w.name warehouse_name,i.id item_id,i.name item_name,i.code item_code,u.name base_unit,i.minimum_stock,COALESCE(b.quantity,0) quantity,COALESCE(b.stock_value,0) stock_value,COALESCE(b.version,-1) version"+POOLS+where+" ORDER BY w.id,i.id LIMIT ? OFFSET ?",a.toArray());for(var r:rows)r.put("averageCost",StockMath.cost(dec(r,"stockValue"),dec(r,"quantity")));return page(rows,count,f);}
    public Object lots(Long branch,long warehouse,long item){commands.require(PermissionCodes.INVENTORY_STOCK_READ);db.one("SELECT id FROM warehouses WHERE branch_id=? AND id=?",access.branch(branch),warehouse);db.one("SELECT id FROM inventory_items WHERE branch_id=? AND id=?",access.branch(branch),item);
        return db.rows("SELECT * FROM stock_lots WHERE warehouse_id=? AND item_id=? ORDER BY expiry_date,lot_code LIMIT 100",warehouse,item);}
    public Object packages(Long branch,long item){commands.require(PermissionCodes.INVENTORY_UNIT_READ);long scope=access.branch(branch);db.one("SELECT id FROM inventory_items WHERE branch_id=? AND id=?",scope,item);
        return db.rows("SELECT id,name,factor FROM inventory_unit_conversions WHERE branch_id=? AND item_id=? AND active=TRUE ORDER BY name,id LIMIT 1001",scope,item);}
    public Object ledger(StockDtos.Filter f){commands.require(PermissionCodes.INVENTORY_STOCK_READ);var s=scope(f,"l");List<Object>a=new ArrayList<>(s.args);String where=s.text;if(f.from()!=null){where+=" AND l.recorded_at>=?";a.add(time(f.from()));}if(f.to()!=null){where+=" AND l.recorded_at<?";a.add(time(f.to()));}
        String base=" FROM stock_ledger l JOIN inventory_items i ON i.id=l.item_id JOIN stock_documents d ON d.id=l.document_id JOIN warehouses w ON w.id=l.warehouse_id JOIN inventory_units u ON u.id=i.base_unit_id";long count=db.jdbc().queryForObject("SELECT COUNT(*)"+base+where,Long.class,a.toArray());a.add(f.size());a.add((long)f.page()*f.size());
        var rows=db.rows("SELECT l.*,d.code,d.kind,i.name item_name,u.name base_unit,w.name warehouse_name"+base+where+" ORDER BY l.id DESC LIMIT ? OFFSET ?",a.toArray());return page(rows,count,f);}

    private List<Map<String,Object>> reportRows(StockDtos.Filter f,boolean export){var s=scope(f,"w");String where=s.text.replace("w.warehouse_id","w.id");Instant from=f.from()==null?Instant.EPOCH:f.from(),to=f.to()==null?Instant.now(clock).plusSeconds(1):f.to();
        List<Object>a=new ArrayList<>(List.of(time(from),time(from),time(from),time(to)));a.addAll(s.args);a.add(export?10001:f.size());a.add(export?0:(long)f.page()*f.size());
        String aggregate=" LEFT JOIN (SELECT l.warehouse_id,l.item_id,SUM(CASE WHEN l.recorded_at<? THEN l.quantity_delta ELSE 0 END) opening_quantity,SUM(CASE WHEN l.recorded_at<? THEN l.value_delta ELSE 0 END) opening_value,"+
            "SUM(CASE WHEN l.quantity_delta>0 AND d.kind NOT IN ('STOCKTAKE','ADJUSTMENT') AND l.phase<>'REVERSAL' THEN l.quantity_delta ELSE 0 END) incoming_quantity,"+
            "SUM(CASE WHEN l.quantity_delta<0 AND d.kind NOT IN ('STOCKTAKE','ADJUSTMENT') AND l.phase<>'REVERSAL' THEN -l.quantity_delta ELSE 0 END) outgoing_quantity,"+
            "SUM(CASE WHEN (d.kind IN ('STOCKTAKE','ADJUSTMENT') OR l.phase='REVERSAL') AND l.quantity_delta>0 THEN l.quantity_delta ELSE 0 END) adjustment_increase,"+
            "SUM(CASE WHEN (d.kind IN ('STOCKTAKE','ADJUSTMENT') OR l.phase='REVERSAL') AND l.quantity_delta<0 THEN -l.quantity_delta ELSE 0 END) adjustment_decrease,"+
            "SUM(CASE WHEN l.value_delta>0 AND d.kind NOT IN ('STOCKTAKE','ADJUSTMENT') AND l.phase<>'REVERSAL' THEN l.value_delta ELSE 0 END) incoming_value,"+
            "SUM(CASE WHEN l.value_delta<0 AND d.kind NOT IN ('STOCKTAKE','ADJUSTMENT') AND l.phase<>'REVERSAL' THEN -l.value_delta ELSE 0 END) outgoing_value,"+
            "SUM(CASE WHEN d.kind IN ('STOCKTAKE','ADJUSTMENT') OR l.phase='REVERSAL' THEN l.value_delta ELSE 0 END) adjustment_value,"+
            "SUM(l.quantity_delta) closing_quantity,SUM(l.value_delta) closing_value FROM stock_ledger l JOIN stock_documents d ON d.id=l.document_id WHERE l.branch_id=? AND l.recorded_at>=? AND l.recorded_at<? GROUP BY l.warehouse_id,l.item_id) period ON period.warehouse_id=w.id AND period.item_id=i.id";
        // Opening is computed independently of the period; the main aggregate must not count earlier movements in period totals.
        aggregate=aggregate.replace("SUM(CASE WHEN l.recorded_at<? THEN l.quantity_delta ELSE 0 END) opening_quantity,SUM(CASE WHEN l.recorded_at<? THEN l.value_delta ELSE 0 END) opening_value,","");
        a=new ArrayList<>(List.of(access.branch(f.branchId()),time(from),time(to),access.branch(f.branchId()),time(from)));a.addAll(s.args);a.add(export?10001:f.size());a.add(export?0:(long)f.page()*f.size());
        String opening=" LEFT JOIN (SELECT warehouse_id,item_id,SUM(quantity_delta) quantity,SUM(value_delta) stock_value FROM stock_ledger WHERE branch_id=? AND recorded_at<? GROUP BY warehouse_id,item_id) opening ON opening.warehouse_id=w.id AND opening.item_id=i.id";
        return db.rows("SELECT w.id warehouse_id,w.name warehouse_name,i.id item_id,i.name item_name,i.code item_code,u.name base_unit,COALESCE(opening.quantity,0) opening_quantity,COALESCE(opening.stock_value,0) opening_value,COALESCE(period.incoming_quantity,0) incoming_quantity,COALESCE(period.outgoing_quantity,0) outgoing_quantity,COALESCE(period.adjustment_increase,0) adjustment_increase,COALESCE(period.adjustment_decrease,0) adjustment_decrease,COALESCE(period.incoming_value,0) incoming_value,COALESCE(period.outgoing_value,0) outgoing_value,COALESCE(period.adjustment_value,0) adjustment_value,COALESCE(opening.quantity,0)+COALESCE(period.closing_quantity,0) closing_quantity,COALESCE(opening.stock_value,0)+COALESCE(period.closing_value,0) closing_value"+POOLS+aggregate+opening+where+" ORDER BY w.id,i.id LIMIT ? OFFSET ?",a.toArray());}
    public Object report(StockDtos.Filter f){commands.require(PermissionCodes.INVENTORY_REPORT_READ);var s=scope(f,"w");long count=db.jdbc().queryForObject("SELECT COUNT(*)"+POOLS+s.text.replace("w.warehouse_id","w.id"),Long.class,s.args.toArray());return page(reportRows(f,false),count,f);}
    public String export(StockDtos.Filter f){commands.require(PermissionCodes.INVENTORY_REPORT_EXPORT);var rows=reportRows(f,true);if(rows.size()>10000)throw StockFailure.invalid("EXPORT_LIMIT_REFINE_FILTERS");boolean costs=access.has(PermissionCodes.INVENTORY_COST_READ);StringBuilder csv=new StringBuilder("\uFEFFKho,Mã vật tư,Vật tư,Đơn vị,Tồn đầu,Nhập,Xuất,Điều chỉnh tăng,Điều chỉnh giảm,Tồn cuối"+(costs?",Giá trị đầu,Giá trị nhập,Giá trị xuất,Giá trị điều chỉnh,Giá trị cuối":"")+"\r\n");
        var keys=new ArrayList<>(List.of("warehouseName","itemCode","itemName","baseUnit","openingQuantity","incomingQuantity","outgoingQuantity","adjustmentIncrease","adjustmentDecrease","closingQuantity"));if(costs)keys.addAll(List.of("openingValue","incomingValue","outgoingValue","adjustmentValue","closingValue"));for(var r:rows)csv.append(String.join(",",keys.stream().map(k->csv(r.get(k))).toList())).append("\r\n");return csv.toString();}
    public static String csv(Object value){String s=Objects.toString(value,"");String trimmed=s.stripLeading();if(!trimmed.isEmpty()&&"=+@-".indexOf(trimmed.charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
    public Object reconciliation(StockDtos.Filter f){commands.require(PermissionCodes.INVENTORY_STOCK_READ);var s=scope(f,"b");var rows=db.rows("SELECT b.warehouse_id,b.item_id,b.quantity,b.stock_value,COALESCE(l.quantity,0) ledger_quantity,COALESCE(l.stock_value,0) ledger_value FROM stock_balances b JOIN inventory_items i ON i.id=b.item_id LEFT JOIN (SELECT warehouse_id,item_id,SUM(quantity_delta) quantity,SUM(value_delta) stock_value FROM stock_ledger WHERE branch_id=? GROUP BY warehouse_id,item_id) l ON l.warehouse_id=b.warehouse_id AND l.item_id=b.item_id"+s.text+" AND (b.quantity<>COALESCE(l.quantity,0) OR b.stock_value<>COALESCE(l.stock_value,0)) LIMIT 100",prepend(access.branch(f.branchId()),s.args));
        var lotDiscrepancies=db.rows("SELECT b.warehouse_id,b.item_id,b.quantity,COALESCE(l.quantity,0) lot_quantity FROM stock_balances b JOIN inventory_items i ON i.id=b.item_id LEFT JOIN (SELECT warehouse_id,item_id,SUM(quantity) quantity FROM stock_lots GROUP BY warehouse_id,item_id) l ON l.warehouse_id=b.warehouse_id AND l.item_id=b.item_id"+s.text+" AND i.track_lots=TRUE AND b.quantity<>COALESCE(l.quantity,0) LIMIT 100",s.args.toArray());
        return Map.of("matches",rows.isEmpty()&&lotDiscrepancies.isEmpty(),"discrepancies",rows,"lotDiscrepancies",lotDiscrepancies);}
    public Object dashboard(StockDtos.Filter f){commands.require(PermissionCodes.INVENTORY_OVERVIEW_READ);var s=scope(f,"w");String where=s.text.replace("w.warehouse_id","w.id");var summary=db.one("SELECT COUNT(DISTINCT i.id) item_count,COALESCE(SUM(COALESCE(b.stock_value,0)),0) stock_value,SUM(CASE WHEN COALESCE(b.quantity,0)<=0 THEN 1 ELSE 0 END) out_of_stock,SUM(CASE WHEN COALESCE(b.quantity,0)<i.minimum_stock THEN 1 ELSE 0 END) low_stock"+POOLS+where,s.args.toArray());
        var units=db.rows("SELECT u.id base_unit_id,u.name base_unit,SUM(COALESCE(b.quantity,0)) quantity"+POOLS+where+" GROUP BY u.id,u.name",s.args.toArray());var low=db.rows("SELECT w.name warehouse_name,i.id item_id,i.name item_name,u.name base_unit,i.minimum_stock,COALESCE(b.quantity,0) quantity"+POOLS+where+" AND COALESCE(b.quantity,0)<i.minimum_stock ORDER BY COALESCE(b.quantity,0),i.id LIMIT 20",s.args.toArray());
        List<Object> transitArgs=new ArrayList<>();transitArgs.add(access.branch(f.branchId()));transitArgs.add(access.branch(f.branchId()));String transitWhere=" WHERE (d.branch_id=? OR d.destination_branch_id=?) AND d.status IN ('IN_TRANSIT','PARTIALLY_RECEIVED')";
        if(f.warehouseId()!=null){transitWhere+=" AND (d.warehouse_id=? OR d.destination_warehouse_id=?)";transitArgs.add(f.warehouseId());transitArgs.add(f.warehouseId());}
        if(f.categoryId()!=null){transitWhere+=" AND i.category_id=?";transitArgs.add(f.categoryId());}if(f.itemId()!=null){transitWhere+=" AND i.id=?";transitArgs.add(f.itemId());}
        // Only the local branch's perspective is aggregated; no remote item names or costs are disclosed.
        var transit=db.rows("SELECT SUM(t.dispatched-t.received-t.returned) quantity,u.id base_unit_id,u.name base_unit,SUM(t.remaining_value) transit_value FROM stock_transit t JOIN stock_documents d ON d.id=t.document_id JOIN inventory_items i ON i.id=CASE WHEN d.branch_id=? THEN t.item_id ELSE t.destination_item_id END JOIN inventory_units u ON u.id=i.base_unit_id"+transitWhere+" GROUP BY u.id,u.name",prepend(access.branch(f.branchId()),transitArgs));
        List<Object> flowArgs=new ArrayList<>(s.args);Instant start=f.from()==null?Instant.now(clock).minus(Duration.ofDays(30)):f.from(),end=f.to()==null?Instant.now(clock).plusSeconds(1):f.to();flowArgs.add(time(start));flowArgs.add(time(end));String flowWhere=s.text.replace("w.warehouse_id","l.warehouse_id").replace("w.branch_id","l.branch_id")+" AND l.recorded_at>=? AND l.recorded_at<?";
        var flows=db.rows("SELECT d.kind,SUM(CASE WHEN l.quantity_delta>0 THEN l.quantity_delta ELSE 0 END) incoming_quantity,SUM(CASE WHEN l.quantity_delta<0 THEN -l.quantity_delta ELSE 0 END) outgoing_quantity,u.id base_unit_id,u.name base_unit,SUM(CASE WHEN l.value_delta>0 THEN l.value_delta ELSE 0 END) incoming_value,SUM(CASE WHEN l.value_delta<0 THEN -l.value_delta ELSE 0 END) outgoing_value FROM stock_ledger l JOIN stock_documents d ON d.id=l.document_id JOIN inventory_items i ON i.id=l.item_id JOIN inventory_units u ON u.id=i.base_unit_id"+flowWhere+" GROUP BY d.kind,u.id,u.name",flowArgs.toArray());
        var expired=db.rows("SELECT w.name warehouse_name,i.name item_name,l.lot_code,l.expiry_date,l.quantity FROM stock_lots l JOIN warehouses w ON w.id=l.warehouse_id JOIN inventory_items i ON i.id=l.item_id"+where+" AND l.quantity>0 AND l.expiry_date<=? ORDER BY l.expiry_date LIMIT 20",append(s.args,LocalDate.now(clock.withZone(ZoneId.of("Asia/Ho_Chi_Minh"))).plusDays(30)));
        if(Duration.between(start,end).compareTo(Duration.ofDays(367))>0)throw StockFailure.invalid("DASHBOARD_PERIOD_MAX_YEAR");
        String flowBase=" FROM stock_ledger l JOIN stock_documents d ON d.id=l.document_id JOIN inventory_items i ON i.id=l.item_id JOIN inventory_units u ON u.id=i.base_unit_id";
        var series=db.rows("SELECT CAST(l.recorded_at AS DATE) AS movement_day,u.id base_unit_id,u.name base_unit,SUM(CASE WHEN l.quantity_delta>0 THEN l.quantity_delta ELSE 0 END) incoming_quantity,SUM(CASE WHEN l.quantity_delta<0 THEN -l.quantity_delta ELSE 0 END) outgoing_quantity"+flowBase+flowWhere+" GROUP BY 1,2,3 ORDER BY 1,2",flowArgs.toArray());
        for(var row:series)row.put("day",row.remove("movementDay"));
        var consumption=db.rows("SELECT i.id item_id,i.name item_name,u.name base_unit,-SUM(l.quantity_delta) quantity"+flowBase+flowWhere+" AND d.kind='ISSUE' AND l.issue_type IN ('LAUNDRY','PACKAGING','CONSUMPTION') GROUP BY i.id,i.name,u.name HAVING SUM(l.quantity_delta)<0 ORDER BY u.name,quantity DESC,i.id LIMIT 100",flowArgs.toArray());
        var totals=db.one("SELECT COALESCE(SUM(CASE WHEN d.kind='RECEIPT' THEN l.value_delta ELSE 0 END),0) receipt_value,COALESCE(-SUM(CASE WHEN d.kind='ISSUE' THEN l.value_delta ELSE 0 END),0) issue_value"+flowBase+flowWhere,flowArgs.toArray());
        var recentArgs=new ArrayList<>(flowArgs);recentArgs.add(access.actor());recentArgs.add(access.actor());
        var recent=access.has(PermissionCodes.INVENTORY_DOCUMENT_READ)?db.rows("SELECT DISTINCT d.id,d.code,d.kind,d.status,d.business_at FROM stock_documents d JOIN stock_ledger l ON l.document_id=d.id JOIN inventory_items i ON i.id=l.item_id"+flowWhere+" AND EXISTS(SELECT 1 FROM user_branches ub WHERE ub.user_id=? AND ub.branch_id=d.branch_id) AND (d.destination_branch_id IS NULL OR EXISTS(SELECT 1 FROM user_branches ub WHERE ub.user_id=? AND ub.branch_id=d.destination_branch_id)) ORDER BY d.business_at DESC,d.id DESC LIMIT 10",recentArgs.toArray()):List.<Map<String,Object>>of();
        var result=new LinkedHashMap<String,Object>();result.put("summary",summary);result.put("unitTotals",units);result.put("lowStock",low);result.put("transit",transit);result.put("flows",flows);result.put("expiringLots",expired);result.put("periodFrom",start.toString());result.put("periodTo",end.toString());result.put("series",series);result.put("consumption",consumption);result.put("periodValues",totals);
        // Document navigation requires its own permission and all participating branch scopes.
        result.put("recentDocuments",recent);return result;}
    private Object[] prepend(Object value,List<Object> args){var out=new ArrayList<Object>();out.add(value);out.addAll(args);return out.toArray();}
    private Object[] append(List<Object> args,Object value){var out=new ArrayList<Object>(args);out.add(value);return out.toArray();}
}
